const resultados = $json.resultados || [];

// Retorna UM ITEM por cliente para montar a tabela final
const out = resultados.map(c => {
  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto,
      saldo_num: c.saldo_num,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Pega os clientes (do Webhook ou do Merge) e os investimentos com segurança
const clientes = $input.first().json.body?.clientes 
  ?? $input.first().json.clientes 
  ?? $('Webhook').first().json.body?.clientes 
  ?? $('Webhook').first().json.clientes 
  ?? [];

const investimentos = $input.first().json.investimentos 
  ?? $('Code').first().json.investimentos 
  ?? [];

function parseBRL(valor) {
  if (typeof valor === 'number') return valor;
  if (!valor) return 0;
  const s = String(valor).replace("R$", "").replace(/\./g, "").replace(",", ".").replace(/[^\d.]/g, "").trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

const focoPerfil = {
  "Conservador": "Foco em renda fixa e segurança",
  "Moderado": "Mix equilibrado entre renda fixa e variável",
  "Arrojado": "Ênfase em ações e maior potencial de retorno"
};

const resultados = [];

for (const c of clientes) {
  const saldoOriginal = c.saldo ?? c.saldo_texto ?? c.saldo_num ?? 0;
  const saldoNum = parseBRL(saldoOriginal);
  const saldoTexto = (typeof saldoOriginal === 'string' && saldoOriginal.includes("R$"))
    ? saldoOriginal.trim()
    : saldoNum.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  // Filtra por perfil e saldo
  let opcoes = investimentos.filter(inv => 
    String(inv.perfil).toLowerCase() === String(c.perfil).toLowerCase() && saldoNum >= parseBRL(inv.minimo)
  );
  if (opcoes.length === 0) {
    opcoes = investimentos.filter(inv => String(inv.perfil).toLowerCase() === String(c.perfil).toLowerCase());
  }

  // Ordena por maior rentabilidade para pegar o melhor
  opcoes.sort((a, b) => parseBRL(b.rentabilidade) - parseBRL(a.rentabilidade));
  const melhor = opcoes[0] || investimentos[0];

  const foco = focoPerfil[c.perfil] || `Foco em ${c.perfil}`;
  const minimoFormatado = typeof melhor.minimo === 'number'
    ? melhor.minimo.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
    : `R$ ${melhor.minimo}`;

  // 3 opções de mensagens
  const opcoesMensagens = [
    `Olá ${c.nome}! Pelo seu perfil (${c.perfil} - ${foco}), uma boa opção é **${melhor.produto}** (mínimo ${minimoFormatado}). Com seu saldo atual (${saldoTexto}), você já consegue investir. Rentabilidade: ${melhor.rentabilidade}.`,
    `Oi ${c.nome}! Recomendação para perfil ${c.perfil} (${foco}): **${melhor.produto}** (mínimo ${minimoFormatado}). Seu saldo (${saldoTexto}) já atende o mínimo. Rentabilidade: ${melhor.rentabilidade}.`,
    `${c.nome}, indo direto ao ponto: para o perfil ${c.perfil} (${foco}), **${melhor.produto}** (mínimo ${minimoFormatado}). Você tem ${saldoTexto}, então dá pra aplicar. Rentabilidade: ${melhor.rentabilidade}.`
  ];

  resultados.push({
    nome: c.nome,
    email: c.email,
    perfil: c.perfil,
    saldo_texto: saldoTexto,
    saldo_num: saldoNum,
    recomendacao: {
      perfil: melhor.perfil,
      produto: melhor.produto,
      minimo: melhor.minimo,
      rentabilidade: melhor.rentabilidade
    },
    motivo: foco,
    mensagem_escolhida: opcoesMensagens[0],
    mensagens: opcoesMensagens
  });
}

return [
  {
    json: {
      ok: true,
      total_clientes: clientes.length,
      total_investimentos: investimentos.length,
      resultados: resultados
    }
  }
];

